import pandas as pd
from collections import defaultdict
from decimal import Decimal

def run(inputs: dict[str, pd.DataFrame]) -> dict[str, pd.DataFrame]:
    trades = inputs["trades"].copy()

    # Sort trades by account_id, symbol, trade_ts, then trade_id for deterministic order
    trades = trades.sort_values(
        by=["account_id", "symbol", "trade_ts", "trade_id"],
        ignore_index=True
    )

    sell_results_rows = []
    open_lots_rows = []

    # Group by (account_id, symbol) and process each group
    for (account_id, symbol), group in trades.groupby(["account_id", "symbol"], sort=False):
        group = group.reset_index(drop=True)

        # Open lots for this (account_id, symbol): list of [lot_trade_id, remaining_qty, price]
        open_lots_list = []

        for idx, row in group.iterrows():
            trade_id = row["trade_id"]
            side = row["side"]
            qty = row["qty"]
            price = row["price"]

            if side == "BUY":
                # Open a new lot
                open_lots_list.append({
                    "lot_trade_id": trade_id,
                    "remaining_qty": qty,
                    "price": price
                })
            elif side == "SELL":
                # Match against open lots FIFO
                matched_qty = 0
                realized_pnl = 0.0
                still_to_sell = qty

                # Iterate through open lots and consume oldest first
                for lot in open_lots_list:
                    if still_to_sell <= 0:
                        break

                    if lot["remaining_qty"] > 0:
                        take = min(lot["remaining_qty"], still_to_sell)
                        realized_pnl += take * (price - lot["price"])
                        lot["remaining_qty"] -= take
                        matched_qty += take
                        still_to_sell -= take

                short_qty = qty - matched_qty

                sell_results_rows.append({
                    "trade_id": trade_id,
                    "matched_qty": matched_qty,
                    "short_qty": short_qty,
                    "realized_pnl": realized_pnl
                })

        # Add remaining lots to output
        for lot in open_lots_list:
            if lot["remaining_qty"] > 0:
                open_lots_rows.append({
                    "lot_trade_id": lot["lot_trade_id"],
                    "account_id": account_id,
                    "symbol": symbol,
                    "remaining_qty": lot["remaining_qty"],
                    "price": lot["price"]
                })

    # Create output DataFrames
    if sell_results_rows:
        sell_results_df = pd.DataFrame(sell_results_rows)
        sell_results_df = sell_results_df[["trade_id", "matched_qty", "short_qty", "realized_pnl"]]
    else:
        sell_results_df = pd.DataFrame(columns=["trade_id", "matched_qty", "short_qty", "realized_pnl"])

    if open_lots_rows:
        open_lots_df = pd.DataFrame(open_lots_rows)
        open_lots_df = open_lots_df[["lot_trade_id", "account_id", "symbol", "remaining_qty", "price"]]
    else:
        open_lots_df = pd.DataFrame(columns=["lot_trade_id", "account_id", "symbol", "remaining_qty", "price"])

    # Ensure correct dtypes
    sell_results_df = sell_results_df.astype({
        "trade_id": "int64",
        "matched_qty": "int64",
        "short_qty": "int64",
        "realized_pnl": "float64"
    })

    open_lots_df = open_lots_df.astype({
        "lot_trade_id": "int64",
        "account_id": "int64",
        "symbol": "object",
        "remaining_qty": "int64",
        "price": "float64"
    })

    return {
        "sell_results": sell_results_df,
        "open_lots": open_lots_df
    }
